15		private static _handleEolEdits(editor: ICodeEditor, edits: TextEdit[]): ISingleEditOperation[] {
16			let newEol: EndOfLineSequence | undefined = undefined;
17			const singleEdits: ISingleEditOperation[] = [];
18	
19			for (const edit of edits) {
20				if (typeof edit.eol === 'number') {
21					newEol = edit.eol;
22				}
23				if (edit.range && typeof edit.text === 'string') {
24					singleEdits.push(edit);
25				}
26			}
27	
28			if (typeof newEol === 'number') {
29				if (editor.hasModel()) {
30					editor.getModel().pushEOL(newEol);
31				}
32			}
33	
34			return singleEdits;
35		}
36	
37		private static _isFullModelReplaceEdit(editor: ICodeEditor, edit: ISingleEditOperation): boolean {
38			if (!editor.hasModel()) {
39				return false;
40			}
41			const model = editor.getModel();
42			const editRange = model.validateRange(edit.range);
43			const fullModelRange = model.getFullModelRange();
44			return fullModelRange.equalsRange(editRange);
45		}
46	
47		static execute(editor: ICodeEditor, _edits: TextEdit[], addUndoStops: boolean) {
48			if (addUndoStops) {
49				editor.pushUndoStop();
50			}
51			const scrollState = StableEditorScrollState.capture(editor);
52			const edits = FormattingEdit._handleEolEdits(editor, _edits);
53			if (edits.length === 1 && FormattingEdit._isFullModelReplaceEdit(editor, edits[0])) {
54				// We use replace semantics and hope that markers stay put...
55				editor.executeEdits('formatEditsCommand', edits.map(edit => EditOperation.replace(Range.lift(edit.range), edit.text)));
56			} else {
57				editor.executeEdits('formatEditsCommand', edits.map(edit => EditOperation.replaceMove(Range.lift(edit.range), edit.text)));
58			}
59			if (addUndoStops) {
60				editor.pushUndoStop();
61			}
62			scrollState.restoreRelativeVerticalPositionOfCursor(editor);
63		}
